S.append(grid([[P("Lvl", cellhead), P("Class", cellhead), P("What you get", cellhead), P("Where in the story", cellhead)]] + [[P(a, cellb), P(b, cell), P(c, cell), P(d_, cell)] for a, b, c, d_ in rows], [0.4*inch, 0.85*inch, 2.9*inch, W-4.15*inch]))
S.append(PageBreak()); S.append(P("Snapshots by arc, with the feat checked", h2)); S.append(rule())
def snap(name, where, lvl, lines, checked):
    content = [P(name, snapname), P(where + "  ·  " + lvl, stattag)] + [P(l, snapline) for l in lines] + [P("<b>The feat, checked.</b> " + checked, snapline)]
    t = Table([[content]], colWidths=[W]); t.setStyle(TableStyle([("BACKGROUND",(0,0),(-1,-1),PARCH),("LINEBEFORE",(0,0),(0,-1),2.5,GREEN),("LEFTPADDING",(0,0),(-1,-1),10),("RIGHTPADDING",(0,0),(-1,-1),10),("TOPPADDING",(0,0),(-1,-1),7),("BOTTOMPADDING",(0,0),(-1,-1),7)]))
    return KeepTogether([t, Spacer(1,7)])
S.append(snap("The marine", "Doom, Doom II, Doom 64 · the man before the Slayer", "Levels 1–6 · Fighter 1–6", ["Str 16, Dex 16, Con 15, Int 8, Wis 12, Cha 8 · <b>AC</b> 16 (green armor) · <b>HP</b> 13 → 66 · combat shotgun +5 → +9, chaingun, rockets, plasma, a BFG he finds on the floor · Action Surge, crits on 19–20, two attacks by level 5"], "Phobos, Deimos, Hell and Earth on one man's shotgun. A level-6 fighter with firearms clears imps and pinkies by the room (CR 1 and 2); the Cyberdemon and Spiderdemon of 1993 are CR 12 and 15 bosses he beats with the BFG picked up a level earlier, which is the game: the gun does the boss. Doom 64 ends with him staying in Hell, which is where the Sentinels find him."))
S.append(snap("The Outlander, the Divinity Machine", "the codex of Doom (2016); the opening of The Dark Ages", "Levels 7–9 · Barbarian 1–3", ["<b>HP</b> 94 → 133 · Rage, Reckless Attack · at level 9: <b>Str 24, Con 22</b>, Divine Fury, the Praetor Suit · <b>AC</b> 20"], "The Sentinels put a marine in their arena and he tears demons apart with his hands; the Seraphim puts him in the Divinity Machine and a Slayer walks out. On the sheet that is Rage, then the Divinity feature setting Strength and Constitution past the ceiling, the same tool as Smasher's frame and Guy's Gates: a canon event, not a point buy."))
S.append(snap("The Dark Ages, and Revelations", "Doom: The Dark Ages (2025) and its expansion · the Sentinel wars", "Levels 10–14 · Barbarian 4–8", ["<b>HP</b> 146 → 198 · Extra Attack from both classes (two attacks), Fast Movement, Fanatical Focus, Feral Instinct · Shield Saw, Chain Spear, mace, flail, gauntlet; the Atlan and Serrat as set pieces · Grappler, Athlete"], "The Maykrs' weapon on a leash. Kreed Maykr is a CR 10 schemer in a floating chair and the shield saw bisects him in a turn. Ahzrak, the prince of Hell, is a CR 20 archfiend with the Heart of Argent in his chest: a level-13 Slayer with a shield empowered by Thira's ritual (treat it as the Sentinel Hammer, early) beats him in his own fortress because the fight is a Grappler's: Punch and Grab, advantage against what he holds, and the Heart torn out by hand at Strength 24. Revelations is the same man climbing out of Hell's Core with a spear on a chain."))
S.append(snap("The Unholy Crusade and the burial", "the Slayer's Testament; the codex of Doom (2016)", "Levels 15–17 · Barbarian 9–11", ["<b>HP</b> 211 → 237 · Brutal Strike, Zealous Presence, <b>Relentless Rage</b> · the Crucible"], "The Titan is a demon the size of a hill, CR 30, with something like 900 hit points and regeneration. The Crucible card is written for this: 12d12+7 that nothing resists, and a cut-in-half clause at 150. He wears it down through its own army first, which the Testament describes as ages of slaughter, and the blade ends it. Then the Hell Priests do the only thing that ever worked on him: they bury him alive, because Relentless Rage at a +12 Constitution save means they never saw him at 0."))
S.append(snap("Doom (2016) and Doom Eternal", "Mars, then Earth · the Slayer most people meet first", "Levels 18–19 · Barbarian 12–13", ["<b>HP</b> 250 → 263 (+60 shielding) · Speedy, Improved Brutal Strike · the Eternal loop: Meat Hook, Dash, Flame Belch, Ice Bomb, Blood Punch, Glory Kills, the BFG"], "The Cyberdemon (CR 22) dies twice; the Hell Guards and the Spider Mastermind go the same way; the Doom Hunters and the Marauder are the first demons built to fight him and they still lose. The Khan Maykr is a CR 26 celestial-tier ruler with legendary resistances: the Crucible's cut-in-half clause after a fight that burns her shields is her death. The Icon of Sin is a creature the size of a mountain, Gargantuan twice over, and the game's answer is to strip its armor plate by plate with everything on the sheet, then put the Crucible through its skull: 12d12+7 ignoring immunity, into a target already under 150, is exactly that cutscene."))
S.append(snap("The Ancient Gods", "Part One and Part Two · Samur Maykr, the Dark Lord, the sarcophagus", "Level 20 · Barbarian 14 / Fighter 6", ["The headline block: 298 HP + 60 shielding, AC 20, the Sentinel Hammer, three BFG cells, three Crucible charges, <b>Rage Beyond Death</b>"], "Samur Maykr, the Seraphim who made him, is a CR 24 celestial and dies to the man he built. Davoth, the Dark Lord, is the first being, a CR 30 in an Argent-powered suit with his own shield and sword: the fight is a shield-parry duel the Slayer's own kit was built to mirror, and it ends with the Crucible in his chest, which is the one death that silences every demon in existence. Then the Maykrs seal the Slayer in a sarcophagus, which is the only honest ending for a sheet whose owner cannot be killed."))
S.append(P("Alternates, and a DM's dial", h2)); S.append(rule())
S.append(P("<b>Pure Fighter 20</b> gets four attacks and the arsenal sings, but you lose Rage Beyond Death, which is the whole legend. <b>Barbarian 20</b> gets the Primal Champion capstone (Str 24, Con 24) honestly instead of through the Divinity Machine, but loses Archery, Action Surge and the second attack at level 5, and he was a marine first. <b>2014 rules:</b> Variant Human (Sharpshooter at 1), the Zealot as printed (Rage Beyond Death is native), Gunner for the firearms."))
S.append(P("<b>The dial.</b> Everything here is canon-sized. For a table: make the Crucible's cut-in-half clause 100 hit points, the BFG 12d10, Blood Punch 6d10, and give any creature with Legendary Resistance resistance to the BFG. That is still him; it is just not the one who killed a god."))
doc.build(S, onFirstPage=on_page, onLaterPages=on_page); print("ok")
